<script>document.getElementById('add-variant').onclick=function(){var box=document.getElementById('variants'),i=box.children.length,row=document.createElement('div');row.className='variant-row';row.innerHTML=['name','sku','barcode','cost_price','price','compare_at_price','weight'].map(function(n){return '<input name="variants['+i+']['+n+']" placeholder="'+n.replace('_',' ')+'" '+(n==='sku'||n==='price'?'required':'')+'>'}).join('')+'<input type="hidden" name="variants['+i+'][is_active]" value="1">';box.appendChild(row)}</script>
